{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Ondansetron has high absolute oral bioavailability (~85%) in humans, but it is a monobasic drug lacking the amidine-carboxylate zwitterion present in the query; its high F is not transferable to the query's permeability-limited absorption.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Indomethacin is almost completely absorbed in adults (F~98%), showing that a lipophilic carboxylic acid can be highly bioavailable; however, the query combines a carboxylate with a strongly basic amidine, creating a zwitterion that indomethacin does not model.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C47"],
      "claim": "Telmisartan, a benzimidazole carboxylic acid, has absolute F~42% in fasting volunteers, above the 20% threshold; despite some acid/benzimidazole overlap, it lacks the amidine and is not a zwitterion, so it does not support high F for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Indomethacin in preterm infants had F=13%, an affirmative measurement below 20% for a carboxylic acid drug; although the immature-infant condition limits transferability, it demonstrates that ionizable acidic drugs can fall below the threshold when absorption is poor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin, a basic drug with an imidazole and amide, has absolute F~57.8% in healthy subjects; its high F is not applicable to the query because it lacks the anionic carboxylate that pairs with the amidine to reduce membrane permeability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is dabigatran, a zwitterionic direct thrombin inhibitor with very low oral bioavailability (<20%); the marketed oral form is the etexilate prodrug. The retrieved high-F analogues lack the amidine-carboxylate zwitterion and are therefore not transferable despite high assay-transfer scores. Prediction: low.",
  "evidence_gaps": [
    "No direct experimental record for the query (dabigatran) was supplied; the low-F conclusion relies on established clinical pharmacology rather than the retrieved analogues.",
    "The only sub-20% retrieved record (indomethacin in preterm infants) is from a special population with limited transferability.",
    "Retrieved high-F analogues do not contain the simultaneous strong amidine and carboxylic acid that dominate the query's absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

